#include "countries/countries_instance.h"
int main(){auto c=Countries::CountriesInstance();std::cout<<c.list().size()<<'\n';for(const auto&i:c.list()){std::cout<<i.iso2.toStdString()<<'\t'<<i.name.toStdString()<<'\t'<<i.alternativeName.toStdString()<<'\n';}for(auto phone:{"14031234567","76123456789","79991234567","449876543210","59991234","","99999999"})for(int flags=0;flags<16;++flags){auto r=c.format({.phone=QString::fromLatin1(phone),.onlyGroups=bool(flags&1),.skipCode=bool(flags&2),.incomplete=bool(flags&4),.onlyCode=bool(flags&8)});std::cout<<phone<<'\t'<<flags<<'\t'<<r.formatted.toStdString()<<'\t'<<r.code.toStdString()<<'\t';for(auto g:r.groups)std::cout<<g<<',';std::cout<<'\n';}}
